<script setup>
import { onMounted,ref } from 'vue'
import { RouterLink } from 'vue-router'
import { useLearningStore } from '../api'
const api=useLearningStore(),data=ref(null),error=ref(''),loading=ref(true),email=ref(''),password=ref(''),logging=ref(false)
async function load(){loading.value=true;error.value='';try{data.value=await api.request('dashboard',undefined,true)}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load)
async function login(){logging.value=true;error.value='';try{const base=(import.meta.env.VITE_API_BASE_URL||'http://localhost:3002/api/v1').replace(/\/$/,'');const r=await fetch(`${base}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});const x=await r.json();if(!r.ok||!x.token)throw new Error((typeof x.error==='string'?x.error:x.message)||'登录失败，请检查邮箱和密码');api.token=x.token;localStorage.setItem('learning_token',x.token);password.value='';await load()}catch(e){error.value=e.message}finally{logging.value=false}}
const format=(value)=>value?new Date(value).toLocaleString('zh-CN'):'—'
</script>
<template><div class="content-page"><div class="section-top"><p class="eyebrow">YOUR LEARNING RECORD</p><span>后端保存</span></div><h2>回望来路，<em>继续前行。</em></h2><p class="page-lead">作答记录与成绩来自后端数据库。继续未完成的练习，也可以登录已有账号。</p><div v-if="loading" class="state-box">正在读取学习记录…</div><div v-if="error" class="state-box error">{{error}} <button @click="load">重试</button></div><template v-if="data"><div class="stats-grid"><div><strong>{{data.totalAnswered}}</strong><span>已答题数</span></div><div><strong>{{data.accuracy==null?'—':`${(data.accuracy*100).toFixed(1)}%`}}</strong><span>正确率</span></div><div><strong>{{data.completedSessions}}</strong><span>完成练习</span></div><div><strong>{{data.wrongCount}}</strong><span>答错次数</span></div></div><h3 class="subhead">学习记录</h3><div class="item-list"><RouterLink v-for="s in data.sessions||[]" :key="s.id" :to="`/sessions/${s.id}`" class="list-row"><span class="item-index">{{s.mode==='exam'?'試':'學'}}</span><div><small>{{format(s.createdAt)}} · {{s.completedAt?'已完成':'进行中'}}</small><h3>{{s.mode==='fun'?(s.activityTitle||'素材练习'):s.level?.toUpperCase()+' 模拟考试'}}</h3><p>已答 {{s.answeredCount}} / {{s.totalQuestions}} 题</p></div><span class="row-action">{{s.completedAt?`${s.score} 分`:'继续 ↗'}}</span></RouterLink><p v-if="!data.sessions?.length" class="empty">还没有练习记录。完成一次练习后，这里会显示真实成绩。</p></div></template><details class="vocab-panel account-panel"><summary>登录已有账号</summary><form @submit.prevent="login"><label>邮箱<input v-model="email" type="email" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><button class="primary-action" type="submit" :disabled="logging">{{logging?'正在登录…':'登录并读取学习记录'}}</button></form></details></div></template>
